/* @socom-skeleton body InitNodeParams__3zdbFPQ23zdb15tag_NODE_PARAMSPCQ23zdb15tag_NODE_PARAMS */
namespace zdb {
void InitNodeParams(tag_NODE_PARAMS* nparams, const tag_NODE_PARAMS* other)
	{
		/* 0x228850: without a source node the defaults are type 1, active, light, fog and
		 * apply_clip; matrix identity. port: m_bbox is left as is there (the ELF copies an
		 * uninitialised stack box). */
		nparams->m_matrix                       = other != NULL ? other->m_matrix : CMatrix::identity;
		if (other != NULL)
			nparams->m_bbox = other->m_bbox;
		nparams->m_type                         = other != NULL ? other->m_type : 1;
		nparams->m_active                       = other != NULL ? other->m_active : true;
		nparams->m_dynamic_motion               = other != NULL ? other->m_dynamic_motion : false;
		nparams->m_dynamic_light                = other != NULL ? other->m_dynamic_light : false;
		nparams->m_landmark                     = other != NULL ? other->m_landmark : false;
		nparams->m_light                        = other != NULL ? other->m_light : true;
		nparams->m_prelight                     = other != NULL ? other->m_prelight : false;
		nparams->m_fog                          = other != NULL ? other->m_fog : true;
		nparams->m_transparent                  = other != NULL ? other->m_transparent : false;
		nparams->m_facade                       = other != NULL ? other->m_facade : false;
		nparams->m_reflective                   = other != NULL ? other->m_reflective : false;
		nparams->m_bumpmap                      = other != NULL ? other->m_bumpmap : false;
		nparams->m_hasDI                        = other != NULL ? other->m_hasDI : false;
		nparams->m_region_shift                 = other != NULL ? other->m_region_shift : 0;
		nparams->m_has_visuals_prior_to_export  = other != NULL ? other->m_has_visuals_prior_to_export : false;
		nparams->m_shadow                       = other != NULL ? other->m_shadow : false;
		nparams->m_worldchild                   = other != NULL ? other->m_worldchild : false;
		nparams->m_char_common                  = other != NULL ? other->m_char_common : false;
		nparams->m_hasVisuals                   = other != NULL ? other->m_hasVisuals : false;
		nparams->m_hasMesh                      = other != NULL ? other->m_hasMesh : false;
		nparams->m_scrolling_texture            = other != NULL ? other->m_scrolling_texture : false;
		nparams->m_light_dynamic                = other != NULL ? other->m_light_dynamic : false;
		nparams->m_light_static                 = other != NULL ? other->m_light_static : false;
		nparams->m_clutter                      = other != NULL ? other->m_clutter : false;
		/* port: unproven - the ELF leaves m_mtx_is_identity and m_NOTUSED alone; cleared here so a new node has no stale bits */
		nparams->m_mtx_is_identity              = other != NULL ? other->m_mtx_is_identity : false;
		nparams->m_NOTUSED                      = other != NULL ? other->m_NOTUSED : false;
		nparams->m_use_parent_bbox              = other != NULL ? other->m_use_parent_bbox : false;
		nparams->m_apply_clip                   = other != NULL ? other->m_apply_clip : true;
	}
}

/* @socom-skeleton body __ct__Q23zdb5CNodeFv */
namespace zdb {
CNode::CNode()
	{
		m_matrix = CMatrix::identity;

		m_name = NULL;
		m_count = 0;
		m_model = NULL;
		m_modelname = NULL;
		m_vid = 0;
		m_nodeEx = NULL;
		m_Atom = NULL;
		m_AtomCnt = 0;
		m_AtomAlloc = 0;
		m_TickNum = -1;
		m_Opacity = 1.0f;
		InitNodeParams(this, NULL);
		/* 0x2285c0: bit 1 (m_modified) and bit 2 (m_character) of +0x9a cleared before
		   InitNodeParams, then bit 0 (m_flatten) set, m_customGlobalLight -1 (no custom light
		   scale), m_frameRendered 0 and m_unused 0; m_character_infov is left as allocated.
		   Was: m_character never cleared (a node in reused heap memory could come out as a
		   character - RenderNode then skips it), m_flatten false, m_customGlobalLight 0. */
		m_modified = false;
		m_character = false;
		m_flatten = true;
		m_customGlobalLight = -1;
		m_parent = NULL; /* port: was `= false` (pointer member) */
		m_unused = 0;
		m_frameRendered = false;
		m_region_mask = 0;

		m_bbox.m_min = CPnt3D::zero;
		m_bbox.m_max = CPnt3D::zero;

		if (NodeUniverse != NULL)
		{
			NodeUniverse->AddNode(this);
		}

		numNodes++;
		m_name = const_cast<char*>(UNNAMED_NODE); /* the shared "NA" name (was a separate literal, so Create/SetName freed it) */
	}
}

/* @socom-skeleton body Copy__Q23zdb5CNodeCFv */
zdb::CNode * zdb::CNode::Copy() const
	{
		return _Copy(NULL);
	}

/* @socom-skeleton body _Copy__Q23zdb5CNodeCFPQ23zdb5CNode */
zdb::CNode * zdb::CNode::_Copy(zdb::CNode *other) const
	{
		/* 0x227e40. A NULL target gets a new CNode and then the same copy as a given one. The
		 * mesh a run of sub-meshes points at is the last clone made (function-local static
		 * last_mesh$1263, guard init$1264). AddVisual/AddDI are inlined there. */
		static CMesh *last_mesh = NULL;

		if (other == NULL)
			other = new CNode();

		if (other != NULL)
		{
			InitNodeParams(other, this);

			if (other->m_name != NULL && other->m_name != UNNAMED_NODE)
				zfree(other->m_name);
			if (m_name != NULL)
				other->m_name = zstrdup(m_name);
			else
				other->m_name = const_cast<char *>(UNNAMED_NODE);

			other->m_Opacity = m_Opacity;

			/* SetModelname, inlined (node_main.cpp lines 2759/2762) */
			if (other->m_modelname != NULL)
			{
				zfree(other->m_modelname);
				other->m_modelname = NULL;
			}
			other->m_modelname = m_modelname != NULL ? zstrdup(m_modelname) : NULL;

			other->SetModel(m_model);
			other->m_flatten = m_flatten;
			other->m_region_mask = m_region_mask;
		}

		other->m_visual.reserve(m_visual.size() + other->m_visual.size());

		for (CVisualVector::const_iterator it = m_visual.begin(); it != m_visual.end(); ++it)
		{
			CVisual *visual = *it;
			CMesh *mesh = visual->m_vtype == 1 ? static_cast<CMesh *>(visual) : NULL;
			CSubMesh *submesh = visual->m_vtype == 2 ? static_cast<CSubMesh *>(visual) : NULL;

			if (mesh != NULL)
			{
				last_mesh = mesh->Clone();
				other->AddVisual(last_mesh);
			}
			else if (submesh != NULL)
			{
				CSubMesh *copy = new CSubMesh(last_mesh);

				if (copy != NULL)
				{
					copy->m_matrix_id = submesh->m_matrix_id;
					other->AddVisual(copy);
				}
			}
			else
			{
				other->AddVisual(visual);
				last_mesh = NULL;
			}
		}

		other->m_di.reserve(m_di.size() + other->m_di.size());

		for (CDIVector::const_iterator it = m_di.begin(); it != m_di.end(); ++it)
			other->AddDI(*it);

		other->ReserveChildren(m_child.size());

		for (CNodeVector::const_iterator it = m_child.begin(); it != m_child.end(); ++it)
		{
			CNode *child = *it;
			CNode *copy;

			if (child->m_type == (u32)TYPE::INSTANCE)
			{
				/* an instance child becomes a new instance of its model at the same place, then
				 * takes the child's parameters, name, opacity, model name and flatten bit */
				CQuat rotation;
				CPnt3D position;

				child->m_matrix.ToQuat(&rotation);
				position.x = child->m_matrix.m_matrix[3][0];
				position.y = child->m_matrix.m_matrix[3][1];
				position.z = child->m_matrix.m_matrix[3][2];

				copy = CreateInstance(child->m_model, &position, &rotation);

				if (copy != NULL)
				{
					InitNodeParams(copy, child);

					if (copy->m_name != NULL && copy->m_name != UNNAMED_NODE)
						zfree(copy->m_name);
					if (child->m_name != NULL)
						copy->m_name = zstrdup(child->m_name);
					else
						copy->m_name = const_cast<char *>(UNNAMED_NODE);

					copy->m_Opacity = child->m_Opacity;

					if (copy->m_modelname != NULL)
					{
						zfree(copy->m_modelname);
						copy->m_modelname = NULL;
					}
					copy->m_modelname = child->m_modelname != NULL ? zstrdup(child->m_modelname) : NULL;

					copy->SetModel(child->m_model);
					copy->m_flatten = child->m_flatten;
					copy->m_region_mask = child->m_region_mask;
				}
			}
			else
			{
				copy = child->_Copy(NULL);
			}

			if (copy != NULL)
				other->AddChild(copy);
		}

		return other;
	}

/* @socom-skeleton body Release__Q23zdb5CNodeFv */
namespace zdb {
short CNode::Release()
	{
		m_count--;

		if (m_count < 0)
		{
			m_count = 0;
		}

		return m_count;
	}
}

/* @socom-skeleton body SetParentHasVisuals__Q23zdb5CNodeFv */
namespace zdb {
void CNode::SetParentHasVisuals()
	{
		/* 0x227c80: mark this node and every ancestor that is not marked yet; a model also
		 * marks its instances (a copy of its instance list is walked) */
		m_hasVisuals = true;

		if (m_parent != NULL && !m_parent->m_hasVisuals)
			m_parent->SetParentHasVisuals();

		CModel* model = dynamic_cast<CModel*>(this);

		if (model == NULL)
			return;

		CRefList instances(model->m_list);

		for (CRefList::iterator i = instances.begin(); i != instances.end(); ++i)
		{
			CNode* node = *i;

			if (node != NULL && !node->m_hasVisuals)
				node->SetParentHasVisuals();
		}
	}
}

